  sink:T("ดูดซับ CO₂", "CO₂ capture"), appr:T("ความนิยม", "Approval"), planAll:T("ทำตามแผน ทุกทวีป", "On-plan, every region"), planIn:T("ทำตามแผน", "On-plan"),
