Object.assign(P, {AIR, LANES, CHOKE, laneOpen, trafficLevels, addGreen, greenInit, placeBuilds, SEASONS, seasonOf, seasonWeight, worldUnlocked, GOALS, goalText, ERAS, worldCheck, copEvent, v1Init, v1Tick});

