  E5:{ree:.4, bat:.3, cu:.3}, I1:{si:.5, cu:.5}, I2:{cu:.6, si:.4}, I4:{cu:1}, P4:{bat:.6, cu:.25, ree:.15}, E6:{bat:.4, cu:.6}, I3:{cu:1},
